139	// TestValidateConceptID verifies upfront concept ID syntax and path containment checks.
140	func TestValidateConceptID(t *testing.T) {
141		invalidIDs := []string{
142			"../escaped",
143			"../../escaped",
144			"/absolute/path",
145			"\\windows\\path",
146			"sub/../../escaped",
147			"a/b/../../..",
148			"a/b/../../../etc/passwd",
149			"concepts/../../log",
150			"concepts/../../AGENTS",
151			"concepts/../../index",
152			"C:\\Windows\\System32",
153			"\\\\unc\\share\\file",
154			"concepts/..\\..\\evil",
155			"index",
156			"log",
157			"AGENTS",
158			"index.md",
159			"log.md",
160			"AGENTS.md",
161			"INDEX.MD",
162			"Log.MD",
163			"agents.md",
164			"",
165			".",
166			"..",
167			"--help",
168			"-h",
169			"-flag",
170			"--flag",
171		}
172		for _, id := range invalidIDs {
173			if err := ValidateConceptID(id); err == nil {
174				t.Errorf("ValidateConceptID(%q) expected error, got nil", id)
175			}
176		}
177	
178		validIDs := []string{
179			"architecture/layers",
180			"decisions/adr-001",
181			"overview",
182			"sub/dir/nested-concept",
183		}
184		for _, id := range validIDs {
185			if err := ValidateConceptID(id); err != nil {
186				t.Errorf("ValidateConceptID(%q) expected valid, got error: %v", id, err)
187			}
188		}
189	}
