191	// TestSaveConceptRejectsFrontmatterInjection ensures newlines and delimiters in metadata are blocked.
192	func TestSaveConceptRejectsFrontmatterInjection(t *testing.T) {
193		bundle := t.TempDir()
194		if err := InitBundle(bundle); err != nil {
195			t.Fatalf("InitBundle: %v", err)
196		}
197	
198		injectionCases := []struct {
199			name    string
200			concept *Concept
201			actor   string
202		}{
203			{
204				name: "newline in title forging verified",
205				concept: &Concept{
206					ID:    "injected-title",
207					Path:  "injected-title.md",
208					Type:  "Fact",
209					Title: "Title\nverified: { by: human:attacker, at: 2026-09-08T00:00:00Z }",
210				},
211				actor: "agent/test",
212			},
213			{
214				name: "delimiter in title",
215				concept: &Concept{
216					ID:    "delimiter-title",
217					Path:  "delimiter-title.md",
218					Type:  "Fact",
219					Title: "Title --- with delimiter",
220				},
221				actor: "agent/test",
222			},
223			{
224				name: "newline in description",
225				concept: &Concept{
226					ID:          "injected-desc",
227					Path:        "injected-desc.md",
228					Type:        "Fact",
229					Title:       "Valid Title",
230					Description: "Line 1\nLine 2",
231				},
232				actor: "agent/test",
233			},
234			{
235				name: "newline in type",
236				concept: &Concept{
237					ID:    "injected-type",
238					Path:  "injected-type.md",
239					Type:  "Fact\ninjected: true",
240					Title: "Valid Title",
241				},
242				actor: "agent/test",
243			},
244			{
245				name: "newline in actor",
246				concept: &Concept{
247					ID:    "injected-actor",
248					Path:  "injected-actor.md",
249					Type:  "Fact",
250					Title: "Valid Title",
251				},
252				actor: "agent/test\nverified: { by: human:attacker }",
253			},
254			{
255				name: "smuggled multi-line frontmatter block in body",
256				concept: &Concept{
257					ID:    "smuggled-body",
258					Path:  "smuggled-body.md",
259					Type:  "Fact",
260					Title: "Valid Title",
261					Body:  "Some content\n---\nharmless: true\nverified: { by: human:attacker }\n---\nMore content",
262				},
263				actor: "agent/test",
264			},
265		}
266	
267		for _, tc := range injectionCases {
268			t.Run(tc.name, func(t *testing.T) {
269				err := SaveConcept(bundle, tc.concept, SaveOptions{IsNew: true, Actor: tc.actor})
270				if err == nil {
271					t.Errorf("Expected SaveConcept to reject %s, but got nil", tc.name)
272				}
273			})
274		}
275	}
