277	// TestAppendLogEntrySanitizesNewlines verifies that log entries cannot spoof dated headings.
278	func TestAppendLogEntrySanitizesNewlines(t *testing.T) {
279		bundle := t.TempDir()
280		if err := InitBundle(bundle); err != nil {
281			t.Fatalf("InitBundle: %v", err)
282		}
283	
284		maliciousDesc := "Updated concept.\n## 2099-01-01\n* **Fake**: Spoofed log entry"
285		if err := AppendLogEntry(bundle, "Update\nInjected", maliciousDesc); err != nil {
286			t.Fatalf("AppendLogEntry failed: %v", err)
287		}
288	
289		logData, err := os.ReadFile(filepath.Join(bundle, "log.md"))
290		if err != nil {
291			t.Fatalf("ReadFile log.md: %v", err)
292		}
293	
294		logStr := string(logData)
295		if strings.Contains(logStr, "\n## 2099-01-01") {
296			t.Errorf("Log spoofing succeeded: found forged heading in log.md: %s", logStr)
297		}
298	}
