300	// TestSerializeConceptYAMLQuoting verifies that special characters like colons and quotes
301	// are safely quoted in YAML and round-trip faithfully.
302	func TestSerializeConceptYAMLQuoting(t *testing.T) {
303		c := &Concept{
304			ID:          "architecture/db",
305			Path:        "architecture/db.md",
306			Type:        "Architecture: Decision",
307			Title:       "Database: PostgreSQL 16 & Redis",
308			Description: "Key-value and relational storage: unified config.",
309			Tags:        []string{"tag:one", "tag:two"},
310			Body:        "# DB Setup\n\nContent here.",
311		}
312	
313		serialized := SerializeConcept(c)
314	
315		// Verify that colons inside title/description/type are quoted
316		if !strings.Contains(serialized, `title: "Database: PostgreSQL 16 & Redis"`) {
317			t.Errorf("Expected title to be quoted with colons, got:\n%s", serialized)
318		}
319	
320		// Verify round-trip parsing
321		parsed, err := ParseConcept(c.Path, serialized)
322		if err != nil {
323			t.Fatalf("Failed to parse serialized concept: %v", err)
324		}
325		if parsed.Title != c.Title {
326			t.Errorf("Round-trip title mismatch: got %q, want %q", parsed.Title, c.Title)
327		}
328		if parsed.Description != c.Description {
329			t.Errorf("Round-trip description mismatch: got %q, want %q", parsed.Description, c.Description)
330		}
331		if parsed.Type != c.Type {
332			t.Errorf("Round-trip type mismatch: got %q, want %q", parsed.Type, c.Type)
333		}
334	}
