336	// TestLoadBundleRejectsExternalSymlinks verifies that LoadBundle refuses to follow symlinks pointing outside the bundle.
337	func TestLoadBundleRejectsExternalSymlinks(t *testing.T) {
338		bundleDir := t.TempDir()
339		if err := InitBundle(bundleDir); err != nil {
340			t.Fatalf("InitBundle failed: %v", err)
341		}
342	
343		outsideDir := t.TempDir()
344		secretFile := filepath.Join(outsideDir, "secret.txt")
345		if err := os.WriteFile(secretFile, []byte("SUPER_SECRET_TOKEN=12345"), 0o600); err != nil {
346			t.Fatalf("Failed to write secret file: %v", err)
347		}
348	
349		// Create symlink inside bundle pointing to secret file outside
350		symlinkPath := filepath.Join(bundleDir, "leak.md")
351		if err := os.Symlink(secretFile, symlinkPath); err != nil {
352			t.Skipf("Symlinks not supported on this platform: %v", err)
353		}
354	
355		_, err := LoadBundle(bundleDir)
356		if err == nil {
357			t.Fatalf("Expected LoadBundle to fail when an external symlink exists, but got nil")
358		}
359		if !strings.Contains(err.Error(), "path traversal denied") && !strings.Contains(err.Error(), "escapes bundle directory") {
360			t.Errorf("Expected path traversal error message, got: %v", err)
361		}
362	}
