426	// TestSaveConceptRejectsSymlinkToReservedOrNonMarkdown verifies that SaveConcept refuses to write through symlinks
427	// targeting reserved documents or non-markdown files within the bundle.
428	func TestSaveConceptRejectsSymlinkToReservedOrNonMarkdown(t *testing.T) {
429		bundleDir := t.TempDir()
430		if err := InitBundle(bundleDir); err != nil {
431			t.Fatalf("InitBundle failed: %v", err)
432		}
433	
434		// Create non-markdown file inside bundle
435		dataJsonPath := filepath.Join(bundleDir, "data.json")
436		if err := os.WriteFile(dataJsonPath, []byte(`{"key":"value"}`), 0o644); err != nil {
437			t.Fatalf("WriteFile data.json: %v", err)
438		}
439	
440		// Create symlink concept_link.md -> data.json
441		symlinkNonMD := filepath.Join(bundleDir, "concept_json.md")
442		if err := os.Symlink("data.json", symlinkNonMD); err != nil {
443			t.Skipf("Symlinks not supported: %v", err)
444		}
445	
446		// Create symlink concept_index.md -> index.md
447		symlinkIndex := filepath.Join(bundleDir, "concept_index.md")
448		if err := os.Symlink("index.md", symlinkIndex); err != nil {
449			t.Skipf("Symlinks not supported: %v", err)
450		}
451	
452		cJSON := &Concept{Path: "concept_json.md", Title: "JSON", Type: "Fact", Body: "PWNED"}
453		if err := SaveConcept(bundleDir, cJSON, SaveOptions{IsNew: false, Actor: "attacker"}); err == nil {
454			t.Errorf("Expected SaveConcept through symlink to non-markdown file to fail, got nil")
455		}
456	
457		cIndex := &Concept{Path: "concept_index.md", Title: "Index", Type: "Fact", Body: "PWNED"}
458		if err := SaveConcept(bundleDir, cIndex, SaveOptions{IsNew: false, Actor: "attacker"}); err == nil {
459			t.Errorf("Expected SaveConcept through symlink to index.md to fail, got nil")
460		}
461	
462		// Ensure index.md content was preserved
463		idxContent, _ := os.ReadFile(filepath.Join(bundleDir, "index.md"))
464		if strings.Contains(string(idxContent), "PWNED") {
465			t.Errorf("index.md was overwritten via symlink!")
466		}
467	}
