530	// TestSaveConceptRejectsSymlinkTraversal verifies that SaveConcept refuses to write through symlinks pointing outside.
531	func TestSaveConceptRejectsSymlinkTraversal(t *testing.T) {
532		bundleDir := t.TempDir()
533		if err := InitBundle(bundleDir); err != nil {
534			t.Fatalf("InitBundle failed: %v", err)
535		}
536	
537		outsideDir := t.TempDir()
538		targetFile := filepath.Join(outsideDir, "critical_config.json")
539		if err := os.WriteFile(targetFile, []byte(`{"protected": true}`), 0o600); err != nil {
540			t.Fatalf("Failed to write target file: %v", err)
541		}
542	
543		// Symlink pointing to external file
544		symlinkPath := filepath.Join(bundleDir, "exploit.md")
545		if err := os.Symlink(targetFile, symlinkPath); err != nil {
546			t.Skipf("Symlinks not supported on this platform: %v", err)
547		}
548	
549		maliciousConcept := &Concept{
550			Path:        "exploit.md",
551			Title:       "Exploit",
552			Type:        "Attack",
553			Description: "Overwrite attack",
554			Body:        "PWNED",
555		}
556	
557		err := SaveConcept(bundleDir, maliciousConcept, SaveOptions{IsNew: false, Actor: "attacker"})
558		if err == nil {
559			t.Fatalf("Expected SaveConcept to reject writing through symlink pointing outside, but got nil")
560		}
561		if !strings.Contains(err.Error(), "path traversal denied") && !strings.Contains(err.Error(), "escapes bundle directory") {
562			t.Errorf("Expected path traversal error message, got: %v", err)
563		}
564	
565		// Verify original file was not modified
566		data, _ := os.ReadFile(targetFile)
567		if string(data) != `{"protected": true}` {
568			t.Errorf("External file was modified! Got: %s", string(data))
569		}
